def extend_list_in_dict(dict_of_lists, key, values):
    """
    Given the dict of key->lists `dict_of_lists`, extends the list at key `key`
    with the values `values` if this list exist. Otherwise, puts the list
    `values` at key `key`.
    """
    if key not in dict_of_lists:
        dict_of_lists[key] = values
    else:
        dict_of_lists[key].extend(values)

def cast_to_unicode(anything):
    """
    If executed with Python 2.7, cast any string that is in `anything`
    to unicode.
    If executed with Python 3, returns `anything`.
    `anything` can be a string, an array, a dict,...
    """
    if sys.version_info[0] == 3:
        return anything

    if isinstance(anything, str):
        return unicode(anything, "utf-8")
    if isinstance(anything, dict):
        cast_dict = dict()
        for key in anything:
            cast_key = cast_to_unicode(key)
            cast_value = cast_to_unicode(anything[key])
            cast_dict[cast_key] = cast_value
        return cast_dict
    if isinstance(anything, list):
        cast_list = []
        for e in anything:
            cast_list.append(cast_to_unicode(e))
        return cast_list
    return anything

def _annotation_tokens_to_dict(self, tokens):
    """
    Transforms the tokens `tokens` that contain an annotation into a dictionary
    that contains the same information.
    @pre: `tokens` really contains an annotation (starting at the beginning of
        the list).
    @raises: - `ValueError` if the precondition is not met.
            - `SyntaxError` if the annotation contains the same key twice.
    """
    if len(tokens) == 0 or tokens[0].type != TerminalType.annotation_start:
        raise ValueError(
            "Tried to parse tokens as if they were an annotation while " + \
            "they weren't"
        )

    result = dict()
    current_key = None
    for token in tokens:
        if token.type == TerminalType.annotation_end:
            break
        elif token.type == TerminalType.key:
            current_key = token.text
        elif token.type == TerminalType.value:
            if current_key in result:
                self.input_file_manager.syntax_error(
                    "Annotation contained the key '" + current_key + \
                    "' twice."
                )
            result[current_key] = token.text

    return result
